# GENERATED by tools/build_bars_kernel.sh - đừng sửa tay, sửa source rồi build lại
"""
BTC Perp — Data Pipeline (Bước 1, bản sửa): raw trades -> clean -> dollar bars
==============================================================================
Chạy được trên Kaggle (chỉ cần pandas + numpy).

Khác bản cũ ở 3 điểm (theo review):
    1. STATEFUL: TradeCleaner và DollarBarBuilder giữ trạng thái giữa các
       lần gọi -> xử lý từng file ngày một mà bar KHÔNG lệch so với chạy
       liền mạch (bar dở dang cuối file được nối tiếp sang file sau).
    2. MEMORY-LEAN: không bao giờ cần load cả 2 năm vào RAM. Mỗi lần chỉ
       giữ 1 file ngày + bars đã đóng. Cột `side` (object) đổi thành
       `is_buy` (bool) ngay khi clean.
    3. OUTLIER: mặc định CHỈ CẢNH BÁO (log-only). Data Bybit là matched
       trades — mọi print đều là giao dịch thật, xóa là làm méo volume.
       Median lăn dùng cửa sổ TRAILING (chỉ nhìn quá khứ) để live tái lập
       được, và tail buffer được carry qua ranh giới file.

Điểm quan trọng (point-in-time) — giữ nguyên bản cũ:
    - Bar "đóng" tại trade CUỐI CÙNG lấp đầy ngưỡng dollar.
    - Timestamp của bar = thời điểm đóng (t_close), KHÔNG phải open.
    - Feature ở bước sau chỉ được dùng thông tin tới lúc bar đóng.

Cách dùng với data thật (Bybit):
    paths = sorted(glob.glob("data/BTCUSDT*.csv.gz"))   # file ngày, ĐÚNG thứ tự
    bars, reports = process_bybit_files(paths, Config())

Schema chuẩn nội bộ sau khi clean:
    ts     : int64   — timestamp mili-giây (UTC)
    price  : float64
    size   : float64 — khối lượng base asset (BTC)
    is_buy : bool    — True nếu phía CHỦ ĐỘNG (taker) là Buy
    tid    : str     — trade id (giữ để dedup xuyên file)
"""

from __future__ import annotations
import numpy as np
import pandas as pd


# =====================================================================
# CONFIG
# =====================================================================
class Config:
    # Ngưỡng dollar cho mỗi bar. LƯU Ý: BTCUSDT Bybit volume thật cỡ vài
    # tỉ USD/ngày -> muốn "vài trăm bar/ngày" thì ngưỡng phải cỡ
    # 10-20 triệu USD. Bắt buộc tune lại sau khi chạy verify_bars trên
    # data thật (xem median_seconds_per_bar).
    DOLLAR_THRESHOLD = 10_000_000.0

    # Outlier: lệch quá X lần so với median TRAILING trong cửa sổ lăn.
    OUTLIER_WINDOW = 500          # số trade (chỉ nhìn quá khứ)
    OUTLIER_MAX_DEV = 0.10        # 10% lệch median -> flag
    REMOVE_OUTLIERS = False       # mặc định chỉ đếm + cảnh báo, KHÔNG xóa

    # Cảnh báo gap: 2 trade liên tiếp cách nhau > X giây -> nghi downtime.
    GAP_WARN_SECONDS = 120

    # Số trade id nhớ lại từ cuối chunk trước để dedup xuyên ranh giới
    # file (file ngày Bybit không chồng lấn, đây chỉ là lưới an toàn).
    DEDUP_TAIL_SIZE = 100_000


# =====================================================================
# 1. SYNTHETIC TRADES — test pipeline khi CHƯA có data Bybit
# =====================================================================
def make_synthetic_trades(n_trades: int = 2_000_000,
                          start_price: float = 60_000.0,
                          seed: int = 42) -> pd.DataFrame:
    """Sinh raw trade giả giống BTC perp: xu hướng, cụm biến động,
    kèm vài outlier + duplicate để test phần cleaning."""
    rng = np.random.default_rng(seed)

    t0 = pd.Timestamp("2024-01-01", tz="UTC").value // 1_000_000  # ms
    gaps_ms = rng.exponential(scale=250, size=n_trades).astype(np.int64) + 1
    ts = t0 + np.cumsum(gaps_ms)

    # Cụm biến động (GARCH-ish), vector hóa bằng lfilter thủ công
    shocks = 0.06 * np.abs(rng.normal(0, 0.0006, n_trades))
    vol = np.empty(n_trades)
    vol[0] = 0.00025
    for i in range(1, n_trades):
        vol[i] = 0.94 * vol[i - 1] + shocks[i]
    returns = rng.normal(0, 1, n_trades) * vol
    price = start_price * np.exp(np.cumsum(returns))

    size = np.exp(rng.normal(-2.0, 1.1, n_trades))  # lognormal, đuôi cá voi

    drift = np.sign(np.diff(price, prepend=price[0]))
    p_buy = 0.5 + 0.08 * drift
    side = np.where(rng.random(n_trades) < p_buy, "Buy", "Sell")

    tid = np.arange(n_trades).astype(str)

    df = pd.DataFrame({"ts": ts, "price": price, "size": size,
                       "side": side, "tid": tid})

    # Chèn "rác" để test cleaning: duplicate ~0.1%, outlier giá ~0.02%
    dup = df.sample(frac=0.001, random_state=seed)
    out_idx = rng.choice(n_trades, size=max(1, n_trades // 5000), replace=False)
    df.loc[out_idx, "price"] *= rng.choice([0.85, 1.15], size=len(out_idx))

    df = pd.concat([df, dup], ignore_index=True)
    df = df.sort_values("ts").reset_index(drop=True)
    return df


# =====================================================================
# 2. LOADER BYBIT — đọc TỪNG file, map về schema raw
# =====================================================================
def load_bybit_csv(path: str) -> pd.DataFrame:
    """Đọc MỘT file trade lịch sử Bybit (.csv / .csv.gz) về schema raw.
    Bybit public data (public.bybit.com/trading/<SYMBOL>/) có cột:
        timestamp (giây, float) | symbol | side | size | price |
        tickDirection | trdMatchID | grossValue | ...
    Đọc từng file một rồi đưa qua process_stream — KHÔNG concat cả 2 năm.
    """
    raw = pd.read_csv(path)
    cols = {c.lower(): c for c in raw.columns}

    def pick(*names):
        for n in names:
            if n in cols:
                return cols[n]
        raise KeyError(f"Không tìm thấy cột nào trong {names}. "
                       f"Cột có sẵn: {list(raw.columns)}")

    ts_col = pick("timestamp", "time")
    ts = (raw[ts_col].astype(float) * 1000).astype(np.int64)  # giây -> ms

    return pd.DataFrame({
        "ts": ts,
        "price": raw[pick("price")].astype(np.float64),
        "size": raw[pick("size", "qty", "amount")].astype(np.float64),
        "side": raw[pick("side")].astype(str).str.capitalize(),
        "tid": raw[pick("trdmatchid", "trade_id", "id")].astype(str),
    })


# =====================================================================
# 3. CLEANER — stateful: dedup + outlier + gap check XUYÊN ranh giới file
# =====================================================================
class TradeCleaner:
    """Làm sạch từng chunk (file ngày). Trạng thái carry qua các lần gọi:
        - tail trade id của chunk trước  -> dedup xuyên ranh giới
        - tail giá của chunk trước       -> median lăn liên tục
        - timestamp cuối cùng            -> gap check xuyên ranh giới
    """

    def __init__(self, cfg: Config = Config()):
        self.cfg = cfg
        self._tail_tids: set[str] = set()
        self._tail_prices = np.array([], dtype=np.float64)
        self._last_ts: int | None = None

    def clean(self, df: pd.DataFrame) -> tuple[pd.DataFrame, dict]:
        cfg = self.cfg
        report: dict = {"rows_in": len(df)}

        # --- sort ổn định theo thời gian (bắt buộc cho dollar bar) ---
        df = df.sort_values("ts", kind="mergesort").reset_index(drop=True)

        # --- (a) dedup: trong chunk + với tail của chunk trước ---
        before = len(df)
        df = df.drop_duplicates(subset="tid", keep="first")
        if self._tail_tids:
            df = df[~df["tid"].isin(self._tail_tids)]
        df = df.reset_index(drop=True)
        report["duplicates_removed"] = before - len(df)

        # --- (b) bỏ giá / size không hợp lệ ---
        before = len(df)
        df = df[(df["price"] > 0) & (df["size"] > 0)].reset_index(drop=True)
        report["nonpositive_removed"] = before - len(df)

        # --- (c) outlier: median TRAILING, tail buffer nối từ chunk trước.
        # Data Bybit là matched trades (mọi print đều thật) nên mặc định
        # chỉ FLAG để soi tay, không xóa. ---
        prices = df["price"].to_numpy(np.float64)
        joined = np.concatenate([self._tail_prices, prices])
        med = (pd.Series(joined)
               .rolling(cfg.OUTLIER_WINDOW, min_periods=20).median()
               .to_numpy()[len(self._tail_prices):])
        med = pd.Series(med).bfill().ffill().to_numpy()
        dev = np.abs(prices - med) / med
        flagged = dev > cfg.OUTLIER_MAX_DEV
        report["outliers_flagged"] = int(flagged.sum())
        if report["outliers_flagged"]:
            report["outlier_examples_utc"] = (
                pd.to_datetime(df.loc[flagged, "ts"].head(5).values,
                               unit="ms", utc=True)
                .strftime("%Y-%m-%d %H:%M:%S").tolist()
            )
        # buffer carry = giá TRƯỚC khi xóa, để median chunk sau khớp
        # hệt với chạy liền mạch
        self._tail_prices = joined[-(cfg.OUTLIER_WINDOW - 1):]
        if cfg.REMOVE_OUTLIERS:
            df = df[~flagged].reset_index(drop=True)
        report["outliers_removed"] = report["outliers_flagged"] \
            if cfg.REMOVE_OUTLIERS else 0

        # --- (d) gap check xuyên ranh giới (chỉ CẢNH BÁO, không sửa) ---
        ts = df["ts"].to_numpy(np.int64)
        if len(ts):
            prev = self._last_ts if self._last_ts is not None else ts[0]
            dt_s = np.diff(ts, prepend=prev) / 1000.0
            gap_mask = dt_s > cfg.GAP_WARN_SECONDS
            report["gaps_over_threshold"] = int(gap_mask.sum())
            if gap_mask.any():
                report["largest_gap_seconds"] = float(dt_s.max())
                report["gap_examples_utc"] = (
                    pd.to_datetime(ts[gap_mask][:5], unit="ms", utc=True)
                    .strftime("%Y-%m-%d %H:%M:%S").tolist()
                )
            self._last_ts = int(ts[-1])
        else:
            report["gaps_over_threshold"] = 0

        # --- (e) schema gọn RAM: side object -> is_buy bool ---
        df = pd.DataFrame({
            "ts": df["ts"].astype(np.int64),
            "price": df["price"].astype(np.float64),
            "size": df["size"].astype(np.float64),
            "is_buy": (df["side"].to_numpy() == "Buy"),
            "tid": df["tid"],
        })

        # nhớ tail tid cho lần gọi sau (bounded để không phình RAM)
        self._tail_tids = set(df["tid"].tail(self.cfg.DEDUP_TAIL_SIZE))

        report["rows_out"] = len(df)
        return df, report


# =====================================================================
# 4. DOLLAR BAR BUILDER — stateful, point-in-time
# =====================================================================
_BAR_COLUMNS = ["t_open", "t_close", "open", "high", "low", "close",
                "vol_base", "vol_dollar", "buy_vol", "sell_vol", "n_trades"]


class DollarBarBuilder:
    """Gộp trade thành dollar bar. Bar đóng khi tổng (price*size) >= ngưỡng.
    Bar dở dang cuối chunk được GIỮ LẠI và nối tiếp ở chunk sau —
    kết quả giống hệt chạy liền mạch trên toàn bộ stream.
    Đây cũng chính là cấu trúc dùng lại cho live/ (streaming từng trade).
    """

    def __init__(self, cfg: Config = Config()):
        self.cfg = cfg
        # trạng thái bar đang mở (None = chưa có trade nào trong bar)
        self._cum_d = 0.0
        self._t_open = 0
        self._o = self._h = self._l = 0.0
        self._buy = self._sell = 0.0
        self._n = 0
        self._active = False

    @property
    def partial_dollar(self) -> float:
        """Dollar volume đã tích trong bar đang mở (chưa đóng)."""
        return self._cum_d

    def update(self, df: pd.DataFrame) -> pd.DataFrame:
        """Nạp thêm trades (đã clean, đã sort), trả về các bar VỪA ĐÓNG."""
        price = df["price"].to_numpy(np.float64)
        size = df["size"].to_numpy(np.float64)
        ts = df["ts"].to_numpy(np.int64)
        is_buy = df["is_buy"].to_numpy(np.bool_)
        thr = self.cfg.DOLLAR_THRESHOLD

        rows = []
        for i in range(len(df)):
            p = price[i]
            if not self._active:
                self._o = self._h = self._l = p
                self._t_open = ts[i]
                self._buy = self._sell = 0.0
                self._cum_d = 0.0
                self._n = 0
                self._active = True
            if p > self._h:
                self._h = p
            if p < self._l:
                self._l = p
            if is_buy[i]:
                self._buy += size[i]
            else:
                self._sell += size[i]
            self._cum_d += p * size[i]
            self._n += 1

            if self._cum_d >= thr:
                rows.append((self._t_open, ts[i], self._o, self._h,
                             self._l, p, self._buy + self._sell,
                             self._cum_d, self._buy, self._sell, self._n))
                self._active = False
                self._cum_d = 0.0

        return self._to_frame(rows)

    @staticmethod
    def _to_frame(rows: list[tuple]) -> pd.DataFrame:
        if rows:
            arr = list(zip(*rows))
        else:
            arr = [[] for _ in _BAR_COLUMNS]
        bars = pd.DataFrame({
            "t_open": np.asarray(arr[0], dtype=np.int64),
            "t_close": np.asarray(arr[1], dtype=np.int64),
            "open": np.asarray(arr[2], dtype=np.float64),
            "high": np.asarray(arr[3], dtype=np.float64),
            "low": np.asarray(arr[4], dtype=np.float64),
            "close": np.asarray(arr[5], dtype=np.float64),
            "vol_base": np.asarray(arr[6], dtype=np.float64),
            "vol_dollar": np.asarray(arr[7], dtype=np.float64),
            "buy_vol": np.asarray(arr[8], dtype=np.float64),
            "sell_vol": np.asarray(arr[9], dtype=np.float64),
            "n_trades": np.asarray(arr[10], dtype=np.int64),
        })
        # timestamp chuẩn = thời điểm ĐÓNG bar (point-in-time)
        bars["dt_close"] = pd.to_datetime(bars["t_close"], unit="ms", utc=True)
        bars["dt_open"] = pd.to_datetime(bars["t_open"], unit="ms", utc=True)
        # order flow imbalance (tot > 0 vì mọi trade sau clean có size > 0)
        tot = bars["buy_vol"] + bars["sell_vol"]
        bars["ofi"] = (bars["buy_vol"] - bars["sell_vol"]) / tot
        return bars


# =====================================================================
# 5. DRIVER — chạy cả pipeline trên iterator của chunks / file ngày
# =====================================================================
def process_stream(chunks, cfg: Config = Config()):
    """chunks: iterator các DataFrame raw (schema ts/price/size/side/tid),
    ĐÚNG thứ tự thời gian. Trả về (bars, reports)."""
    cleaner = TradeCleaner(cfg)
    builder = DollarBarBuilder(cfg)
    all_bars, reports = [], []
    for chunk in chunks:
        clean, report = cleaner.clean(chunk)
        all_bars.append(builder.update(clean))
        reports.append(report)
    bars = pd.concat(all_bars, ignore_index=True)
    # phần dollar dở dang cuối stream — báo lại, không âm thầm vứt
    if reports and builder.partial_dollar > 0:
        reports[-1]["tail_partial_dollar_dropped"] = builder.partial_dollar
    return bars, reports


def process_bybit_files(paths: list[str], cfg: Config = Config()):
    """Tiện ích: chạy trên danh sách file ngày Bybit (đã sort tăng dần).
    Mỗi thời điểm chỉ có 1 file trong RAM."""
    return process_stream((load_bybit_csv(p) for p in paths), cfg)


# =====================================================================
# 6. VERIFY — kiểm tra chất lượng bar (dùng để tune DOLLAR_THRESHOLD)
# =====================================================================
def verify_bars(bars: pd.DataFrame) -> dict:
    logret = np.log(bars["close"] / bars["close"].shift(1)).dropna()
    return {
        "n_bars": len(bars),
        "span": f'{bars["dt_open"].iloc[0]} -> {bars["dt_close"].iloc[-1]}',
        "bars_per_day": float(len(bars) / max(
            (bars["t_close"].iloc[-1] - bars["t_open"].iloc[0]) / 86_400_000, 1e-9)),
        "median_trades_per_bar": float(bars["n_trades"].median()),
        "median_seconds_per_bar": float(
            (bars["t_close"] - bars["t_open"]).median() / 1000.0),
        "logret_std": float(logret.std()),
        "logret_skew": float(logret.skew()),
        "logret_kurtosis_excess": float(logret.kurtosis()),  # 0 = chuẩn
        "ofi_mean": float(bars["ofi"].mean()),
        "ofi_std": float(bars["ofi"].std()),
        "any_nan": bool(bars.isna().any().any()),
    }


